"""
views/vm_create_dialog.py — dialog for creating a new VM.

Presents a form collecting:
  - Name, display label, trust level
  - vCPUs, memory
  - Disk path + size
  - Optional ISO for installation media
  - Network bridge selection
  - Firmware (UEFI / BIOS)

Calls LibvirtManager.build_domain_xml() then define_domain() on confirm.
"""

import gi
gi.require_version("Gtk", "4.0")
gi.require_version("Adw", "1")

from gi.repository import Gtk, Adw, GLib
from typing import Callable

from ..backend.libvirt_manager import (
    LibvirtManager, TRUST_LABELS, TRUST_LEVELS, DEFAULT_TRUST_LEVELS
)

# Available libvirt networks
_DEFAULT_NETWORKS = ["bulwark-appvms", "bulwark-internal", "default"]


class VMCreateDialog(Adw.Dialog):
    """
    Adw.Dialog-based VM creation form.
    on_created(name) is called if the VM is successfully defined.
    """

    def __init__(
        self,
        manager: LibvirtManager,
        on_created: Callable[[str], None],
        parent: Gtk.Widget,
    ):
        super().__init__()
        self._mgr        = manager
        self._on_created = on_created

        self.set_title("New Virtual Machine")
        self.set_content_width(520)
        self.set_content_height(640)

        # ── Toolbar view ─────────────────────────────────────────────────
        toolbar = Adw.ToolbarView()
        self.set_child(toolbar)

        header = Adw.HeaderBar()
        toolbar.add_top_bar(header)

        # Cancel button
        btn_cancel = Gtk.Button(label="Cancel")
        btn_cancel.connect("clicked", lambda _: self.close())
        header.pack_start(btn_cancel)

        # Create button
        self._btn_create = Gtk.Button(label="Create")
        self._btn_create.add_css_class("suggested-action")
        self._btn_create.connect("clicked", self._on_create_clicked)
        header.pack_end(self._btn_create)

        # ── Scrollable form ───────────────────────────────────────────────
        clamp = Adw.Clamp()
        clamp.set_maximum_size(480)
        clamp.set_margin_top(16)
        clamp.set_margin_bottom(16)
        clamp.set_margin_start(16)
        clamp.set_margin_end(16)

        scroll = Gtk.ScrolledWindow()
        scroll.set_policy(Gtk.PolicyType.NEVER, Gtk.PolicyType.AUTOMATIC)
        scroll.set_vexpand(True)
        scroll.set_child(clamp)
        toolbar.set_content(scroll)

        body = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=16)
        clamp.set_child(body)

        # ── Error banner ──────────────────────────────────────────────────
        self._error_banner = Adw.Banner()
        self._error_banner.set_revealed(False)
        body.append(self._error_banner)

        # ── Identity group ────────────────────────────────────────────────
        id_group = Adw.PreferencesGroup()
        id_group.set_title("Identity")
        body.append(id_group)

        # VM name (libvirt domain name — no spaces)
        self._name_row = Adw.EntryRow()
        self._name_row.set_title("VM name")
        self._name_row.set_input_hints(Gtk.InputHints.NO_SPELLCHECK)
        self._name_row.connect("changed", self._validate)
        id_group.add(self._name_row)

        # Display label (optional friendly name)
        self._label_row = Adw.EntryRow()
        self._label_row.set_title("Display label (optional)")
        id_group.add(self._label_row)

        # Trust level — populated from live manager defs
        self._trust_row = Adw.ComboRow()
        self._trust_row.set_title("Trust level")
        defs = manager.get_trust_defs()
        trust_model = Gtk.StringList()
        self._trust_keys: list[str] = []
        for key, defn in sorted(defs.items(), key=lambda x: x[1].get("sort", 99)):
            if key in ("system", "unknown"):
                continue
            trust_model.append(defn.get("label", key))
            self._trust_keys.append(key)
        self._trust_row.set_model(trust_model)
        default_trust = "trusted"
        idx = self._trust_keys.index(default_trust) if default_trust in self._trust_keys else 0
        self._trust_row.set_selected(idx)
        id_group.add(self._trust_row)

        # ── Hardware group ────────────────────────────────────────────────
        hw_group = Adw.PreferencesGroup()
        hw_group.set_title("Hardware")
        body.append(hw_group)

        # vCPUs
        self._vcpu_row = Adw.SpinRow.new_with_range(1, 32, 1)
        self._vcpu_row.set_title("vCPUs")
        self._vcpu_row.set_value(2)
        hw_group.add(self._vcpu_row)

        # Memory
        self._mem_row = Adw.SpinRow.new_with_range(256, 131072, 256)
        self._mem_row.set_title("Memory (MB)")
        self._mem_row.set_value(2048)
        hw_group.add(self._mem_row)

        # Firmware
        self._firmware_row = Adw.ComboRow()
        self._firmware_row.set_title("Firmware")
        fw_model = Gtk.StringList()
        fw_model.append("UEFI (recommended)")
        fw_model.append("BIOS (legacy)")
        self._firmware_row.set_model(fw_model)
        hw_group.add(self._firmware_row)

        # ── Storage group ─────────────────────────────────────────────────
        storage_group = Adw.PreferencesGroup()
        storage_group.set_title("Storage")
        body.append(storage_group)

        # Disk image path
        self._disk_row = Adw.EntryRow()
        self._disk_row.set_title("Disk image path (.qcow2)")
        self._disk_row.set_text("/var/lib/bulwarkos/images/")
        self._disk_row.connect("changed", self._validate)
        storage_group.add(self._disk_row)

        # Disk size
        self._disk_size_row = Adw.SpinRow.new_with_range(1, 2000, 1)
        self._disk_size_row.set_title("Disk size (GB)")
        self._disk_size_row.set_value(20)
        storage_group.add(self._disk_size_row)

        # ── Installation media ────────────────────────────────────────────
        iso_group = Adw.PreferencesGroup()
        iso_group.set_title("Installation media")
        iso_group.set_description("Optional — attach an ISO for OS installation on first boot.")
        body.append(iso_group)

        self._iso_row = Adw.EntryRow()
        self._iso_row.set_title("ISO path (optional)")
        iso_group.add(self._iso_row)

        # ── Network ───────────────────────────────────────────────────────
        net_group = Adw.PreferencesGroup()
        net_group.set_title("Network")
        body.append(net_group)

        self._net_row = Adw.ComboRow()
        self._net_row.set_title("Virtual network")
        net_model = Gtk.StringList()
        for n in _DEFAULT_NETWORKS:
            net_model.append(n)
        self._net_row.set_model(net_model)
        net_group.add(self._net_row)

        # Initial validation
        self._validate()

    # ------------------------------------------------------------------ #
    # Validation                                                           #
    # ------------------------------------------------------------------ #

    def _validate(self, *_):
        name = self._name_row.get_text().strip()
        disk = self._disk_row.get_text().strip()

        name_ok = bool(name) and " " not in name and name.replace("-", "").replace("_", "").isalnum()
        disk_ok = disk.endswith(".qcow2")

        self._btn_create.set_sensitive(name_ok and disk_ok)

        if name and not name_ok:
            self._name_row.add_css_class("error")
        else:
            self._name_row.remove_css_class("error")

    # ------------------------------------------------------------------ #
    # Create                                                               #
    # ------------------------------------------------------------------ #

    def _on_create_clicked(self, _btn):
        name       = self._name_row.get_text().strip()
        label      = self._label_row.get_text().strip() or None
        trust_idx  = self._trust_row.get_selected()
        trust      = self._trust_keys[trust_idx]
        vcpus      = int(self._vcpu_row.get_value())
        memory_mb  = int(self._mem_row.get_value())
        disk_path  = self._disk_row.get_text().strip()
        disk_gb    = int(self._disk_size_row.get_value())
        iso_path   = self._iso_row.get_text().strip() or None
        net_idx    = self._net_row.get_selected()
        network    = _DEFAULT_NETWORKS[net_idx]
        firmware   = "efi" if self._firmware_row.get_selected() == 0 else "bios"

        # Create qcow2 if it doesn't already exist
        import subprocess, os
        if not os.path.exists(disk_path):
            try:
                result = subprocess.run(
                    ["pkexec", "qemu-img", "create", "-f", "qcow2",
                     disk_path, f"{disk_gb}G"],
                    capture_output=True, text=True, timeout=30,
                )
                if result.returncode != 0:
                    self._show_error(f"Failed to create disk image:\n{result.stderr}")
                    return
            except Exception as e:
                self._show_error(f"Failed to create disk image: {e}")
                return

        xml = self._mgr.build_domain_xml(
            name=name,
            vcpus=vcpus,
            memory_mb=memory_mb,
            disk_path=disk_path,
            disk_size_gb=disk_gb,
            iso_path=iso_path,
            network=network,
            firmware=firmware,
        )

        ok, msg = self._mgr.define_domain(xml)
        if not ok:
            self._show_error(msg)
            return

        # Apply trust level and label
        self._mgr.set_trust(name, trust, label)

        self.close()
        self._on_created(name)

    def _show_error(self, message: str):
        self._error_banner.set_title(message)
        self._error_banner.set_revealed(True)
